"use client";

import React, {
  useState,
  useMemo,
  useEffect,
  useCallback,
  useRef,
  FormEvent,
} from "react";
import axios, { AxiosInstance, AxiosRequestConfig, AxiosResponse } from "axios";
import { useRouter, useParams } from "next/navigation";

import { useAuth, type LaravelUser } from "@/hooks/useSanctumAuth";
import { IMAGE_TYPE, getImageUrl, onImageError } from "@/utils/utils";

import styles from "./W-ItemDetailView.module.css";

/* ===================================================================
   型定義
=================================================================== */

interface ApiUser {
  id: number;
  name: string;
  user_image: string | null;
}

interface Item {
  id: number;
  user_id: number;
  name: string;
  brand: string | null;
  price: number | null;
  item_image: string | null;
  remain: number;
  explain: string;
  category: string;
  condition: string | null;
}

interface Comment {
  id: number;
  user: ApiUser;
  comment: string;
  created_at: string;
}

interface ItemDetailResponse {
  item: Item;
  is_favorited: boolean;
  favorites_count: number;
  comments: Comment[];
  errors?: string[];
}

interface RetryableAxiosRequestConfig extends AxiosRequestConfig {
  signal?: AbortSignal;
}

/* ===================================================================
   メインコンポーネント
=================================================================== */

export default function ItemDetailPage() {
  const router = useRouter();
  const params = useParams<{ items_id?: string }>();

  const {
    user: authUser,
    apiClient,
    isAuthenticated,
    isLoading: isAuthLoading,
  } = useAuth();

  // ---------------------------
  // state
  // ---------------------------
  const [item, setItem] = useState<Item | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [itemErrors, setItemErrors] = useState<string[]>([]);
  const [error, setError] = useState<string>("");

  const [isFavorited, setIsFavorited] = useState<boolean>(false);
  const [favoritesCount, setFavoritesCount] = useState<number>(0);

  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState<string>("");
  const [commentErrors, setCommentErrors] = useState<string[]>([]);
  const [isSubmittingComment, setIsSubmittingComment] =
    useState<boolean>(false);

  const hasFetchedRef = useRef<boolean>(false);
  const commentAbortControllerRef = useRef<AbortController | null>(null);

  // ---------------------------
  // itemId
  // ---------------------------
  const itemId = useMemo<number | null>(() => {
    const raw = params?.items_id;
    if (!raw) return null;
    const n = Number(raw);
    if (!Number.isFinite(n) || n <= 0) return null;
    return n;
  }, [params]);

  // ---------------------------
  // 認証中ユーザー
  // ---------------------------
  const extendedUser: LaravelUser | null = authUser ?? null;

  const isOwner = useMemo<boolean>(() => {
    return (
      isAuthenticated &&
      extendedUser !== null &&
      item !== null &&
      extendedUser.id === item.user_id
    );
  }, [isAuthenticated, extendedUser, item]);

  const canInteract = useMemo<boolean>(() => {
    return (
      isAuthenticated &&
      extendedUser !== null &&
      item !== null &&
      extendedUser.id !== item.user_id
    );
  }, [isAuthenticated, extendedUser, item]);

  const isSoldOut = useMemo<boolean>(() => {
    return (item?.remain ?? 0) < 1;
  }, [item]);

  const itemCategories = useMemo<string[]>(() => {
    if (!item?.category) return [];
    try {
      const parsed = JSON.parse(item.category);
      return Array.isArray(parsed) ? parsed : [item.category];
    } catch {
      return [item.category];
    }
  }, [item]);

  const fullItemImageUrl = useMemo<string>(() => {
    const path = item?.item_image ?? null;
    return getImageUrl(path, IMAGE_TYPE.ITEM, 0);
  }, [item?.item_image]);

  // ---------------------------
  // axios wrapper
  // ---------------------------
  const authenticatedFetch = useCallback(
    async (
      config: RetryableAxiosRequestConfig,
    ): Promise<AxiosResponse<unknown>> => {
      if (!apiClient) {
        throw new Error("APIクライアントが準備できていません。");
      }
      return apiClient.request(config as AxiosRequestConfig);
    },
    [apiClient],
  );

  // ---------------------------
  // fetch item
  // ---------------------------
  const fetchData = useCallback(
    async (id: number) => {
      setIsLoading(true);
      setError("");
      setItemErrors([]);

      const endpoint = `/api/item/${id}`;

      try {
        let data: ItemDetailResponse;

        if (isAuthenticated && apiClient) {
          const response = await authenticatedFetch({
            method: "GET",
            url: endpoint,
          });
          data = response.data as ItemDetailResponse;
        } else {
          const response = await axios.get(endpoint, {
            withCredentials: true,
          });
          data = response.data as ItemDetailResponse;
        }

        if (!data.item) {
          setError("商品情報が見つかりませんでした。");
          setItem(null);
          setComments([]);
          setIsFavorited(false);
          setFavoritesCount(0);
          return;
        }

        setItem(data.item);
        setIsFavorited(data.is_favorited ?? false);
        setFavoritesCount(data.favorites_count ?? 0);
        setComments(Array.isArray(data.comments) ? data.comments : []);
      } catch (e) {
        console.error("商品情報の取得に失敗しました:", e);
        setError("商品情報の取得に失敗しました。");
      } finally {
        setIsLoading(false);
      }
    },
    [apiClient, authenticatedFetch, isAuthenticated],
  );

  // ---------------------------
  // effect: 初回ロード
  // ---------------------------
  useEffect(() => {
    if (!itemId) {
      setError("商品IDが不正です。");
      setIsLoading(false);
      return;
    }
    if (isAuthLoading) return;
    if (hasFetchedRef.current && item !== null) return;

    hasFetchedRef.current = true;
    void fetchData(itemId);
  }, [itemId, isAuthLoading, fetchData, item]);

  // ---------------------------
  // お気に入り
  // ---------------------------
  const submitFavorite = useCallback(async () => {
    if (!item) return;

    if (!isAuthenticated) {
      router.push("/login");
      return;
    }

    if (isOwner) {
      setItemErrors(["ご自身の商品には操作できません。"]);
      return;
    }

    const prev = isFavorited;
    setIsFavorited(!prev);
    setFavoritesCount((p) => (prev ? p - 1 : p + 1));

    try {
      const endpoint = `/api/items/${item.id}/favorite`;
      await authenticatedFetch({
        method: prev ? "DELETE" : "POST",
        url: endpoint,
      });
    } catch (e) {
      console.error("お気に入り操作に失敗しました:", e);
      // 巻き戻し
      setIsFavorited(prev);
      setFavoritesCount((p) => (prev ? p + 1 : p - 1));
      setItemErrors(["お気に入り操作に失敗しました。"]);
    }
  }, [item, isAuthenticated, isOwner, isFavorited, authenticatedFetch, router]);

  // ---------------------------
  // コメント投稿
  // ---------------------------
  const submitComment = useCallback(async () => {
    if (isSubmittingComment) return;

    if (!isAuthenticated) {
      router.push("/login");
      return;
    }

    if (!item) {
      setCommentErrors(["商品情報が読み込まれていません。"]);
      return;
    }

    if (!newComment.trim()) {
      setCommentErrors(["コメントを入力してください。"]);
      return;
    }

    if (!extendedUser) {
      setCommentErrors(["ユーザー情報が取得できません。"]);
      return;
    }

    if (commentAbortControllerRef.current) {
      commentAbortControllerRef.current.abort();
    }

    const controller = new AbortController();
    commentAbortControllerRef.current = controller;

    setIsSubmittingComment(true);
    setCommentErrors([]);

    try {
      const response = await authenticatedFetch({
        method: "POST",
        url: "/api/comment",
        data: {
          item_id: item.id,
          comment: newComment,
        },
        signal: controller.signal,
      });

      const res: any = response.data;
      const posted = res?.comment;

      if (posted) {
        const newData: Comment = {
          id: posted.id,
          comment: posted.comment,
          created_at: posted.created_at,
          user: posted.user ?? {
            id: extendedUser.id,
            name: extendedUser.name,
            user_image: extendedUser.user_image ?? null,
          },
        };

        setComments((prev) => [...prev, newData]);
        setNewComment("");
      } else {
        setCommentErrors([
          "コメントの投稿に成功しましたが、データ更新に失敗しました。",
        ]);
      }
    } catch (e: any) {
      if (e?.code === "ERR_CANCELED") {
        // ページ遷移などでキャンセルされた場合
        console.log("コメント送信リクエストはキャンセルされました。");
      } else {
        console.error("コメント投稿に失敗しました:", e);
        setCommentErrors(["コメント投稿に失敗しました。"]);
      }
    } finally {
      setIsSubmittingComment(false);
      commentAbortControllerRef.current = null;
    }
  }, [
    isSubmittingComment,
    isAuthenticated,
    item,
    newComment,
    extendedUser,
    authenticatedFetch,
    router,
  ]);

  // ---------------------------
  // 購入 / マイページ遷移
  // ---------------------------
  const navigateToPurchase = useCallback(() => {
    if (isOwner) {
      router.push("/mypage");
    } else if (isAuthenticated && item) {
      router.push(`/purchase/${item.id}`);
    } else {
      router.push("/login");
    }
  }, [isOwner, isAuthenticated, item, router]);

  const totalLoading = isLoading || isAuthLoading;

  /* ===================================================================
     レンダリング
  =================================================================== */

  // ローディング中
  if (totalLoading) {
    return (
      <div className={`${styles.item_detail_wrapper} bg-gray-100 min-h-screen`}>
        <div className={styles.item_detail_contents}>
          <div className="text-center py-20 w-full">
            <p className="text-xl font-semibold text-gray-600">
              商品情報を読み込み中...
            </p>
          </div>
        </div>
      </div>
    );
  }

  // エラー
  if (error || itemErrors.length > 0) {
    return (
      <div className={`${styles.item_detail_wrapper} bg-gray-100 min-h-screen`}>
        <div className={styles.item_detail_contents}>
          <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded-lg shadow-md my-10 w-full max-w-5xl mx-auto">
            <p className="font-bold">データの取得エラー</p>
            {error && <p>{error}</p>}
            {itemErrors.map((err, index) => (
              <p key={index}>{err}</p>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // 商品がない場合
  if (!item) {
    return (
      <div className={`${styles.item_detail_wrapper} bg-gray-100 min-h-screen`}>
        <div className={styles.item_detail_contents}>
          <div className="text-center py-20 w-full">
            <p className="text-xl font-semibold text-gray-600">
              商品が見つかりませんでした。
            </p>
          </div>
        </div>
      </div>
    );
  }

  // 通常表示
  return (
    <div className={`${styles.item_detail_wrapper} bg-gray-100 min-h-screen`}>
      <div className={styles.item_detail_contents}>
        <div className="flex flex-wrap lg:flex-nowrap w-full max-w-5xl mx-auto bg-white shadow-lg rounded-xl overflow-hidden">
          {/* 商品画像エリア */}
          <div
            className={`${styles.item_detail_image} p-4 lg:p-8 w-full lg:w-1/2`}
          >
            <img
              src={fullItemImageUrl}
              alt="商品写真"
              className={`${styles.item_detail_image1} w-full h-auto object-cover rounded-lg shadow-md`}
              onError={(e) => onImageError(e, item.name)}
            />
          </div>

          {/* 商品情報エリア */}
          <div
            className={`${styles.information} p-4 lg:p-8 w-full lg:w-1/2 space-y-4`}
          >
            <div className={styles.item_detail_name}>
              <h2 className="text-3xl font-extrabold text-gray-800">
                {item.name}
              </h2>
            </div>

            <div
              className={`${styles.item_detail_brand} text-sm text-gray-600`}
            >
              <p className={`${styles.item_detail_brand_1} font-semibold`}>
                ブランド名
              </p>
              <p className={styles.item_detail_brand_2}>
                {item.brand ?? "未登録"}
              </p>
            </div>

            <div className={styles.item_detail_price}>
              {isSoldOut ? (
                <h2 className="text-3xl font-bold text-red-500 bg-red-100 px-3 py-1 rounded inline-block">
                  SOLD OUT
                </h2>
              ) : (
                <h2 className="text-3xl font-bold text-gray-900">
                  <span className="text-xl font-normal">¥</span>
                  {item.price ? item.price.toLocaleString() : "---"}
                  <span className="text-lg font-normal"> (税込)</span>
                </h2>
              )}
            </div>

            <div className="space-y-6 pt-4">
              {/* お気に入り & コメントアイコン */}
              <div className="flex items-center space-x-8">
                {/* お気に入り */}
                <div className="flex items-center">
                  {canInteract ? (
                    <button
                      type="button"
                      onClick={submitFavorite}
                      disabled={totalLoading || isSubmittingComment}
                      className="text-3xl transition-transform transform hover:scale-110 active:scale-90 p-0 m-0 leading-none focus:outline-none disabled:opacity-50"
                    >
                      <span
                        className={`${styles.heart_icon} text-4xl ${
                          isFavorited ? "text-red-500" : ""
                        }`}
                      >
                        {isFavorited ? "❤️" : "🤍"}
                      </span>
                    </button>
                  ) : (
                    <span className="text-3xl text-gray-400 leading-none">
                      🤍
                    </span>
                  )}
                  <p className="text-xl ml-2 font-semibold text-gray-600">
                    {favoritesCount}
                  </p>
                </div>

                {/* コメント数 */}
                <div className="flex items-center">
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="32"
                    height="32"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="1.8"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    className="text-gray-500"
                  >
                    <path d="M21 11.5a8.38 8.38 0 0 1-.6 3.2 12.16 12.16 0 0 1-1.9 2.5c-.8 1.1-1.7 2-2.8 2.5a5.77 5.77 0 0 1-3.6 0c-1.1-.5-2.1-1.4-2.8-2.5a12.16 12.16 0 0 1-1.9-2.5 8.38 8.38 0 0 1-.6-3.2" />
                    <path d="M12 2a10 10 0 1 0 10 10A10 10 0 0 0 12 2z" />
                    <path d="M8 10h8" />
                  </svg>
                  <p className="text-xl ml-2 font-semibold text-gray-600">
                    {comments.length}
                  </p>
                </div>
              </div>

              {/* 購入ボタン */}
              <div className="pt-4">
                <button
                  onClick={navigateToPurchase}
                  disabled={(isSoldOut && !isOwner) || totalLoading}
                  className={`w-full py-3 text-lg font-bold rounded-lg transition duration-200 shadow-lg ${
                    !isSoldOut
                      ? "bg-red-600 text-white hover:bg-red-700 active:bg-red-800"
                      : "bg-gray-400 text-gray-700 cursor-not-allowed"
                  } disabled:bg-gray-400 disabled:opacity-70`}
                >
                  {isOwner
                    ? "マイページへ移動する"
                    : isAuthenticated
                      ? isSoldOut
                        ? "SOLD OUT"
                        : "購入手続きへ"
                      : "ログインして購入"}
                </button>
              </div>
            </div>

            {/* 商品説明 */}
            <div
              className={`${styles.item_detail_explain} mt-8 border-t border-gray-200 pt-6`}
            >
              <h2 className="text-xl font-bold text-gray-800 mb-2">商品説明</h2>
              <h3
                className={`${styles.explain_word} text-gray-700 whitespace-pre-wrap`}
              >
                {item.explain}
              </h3>
            </div>

            {/* 商品情報（カテゴリー） */}
            <div
              className={`${styles.item_detail_category} mt-8 border-t border-gray-200 pt-6`}
            >
              <div>
                <h2 className="text-xl font-bold text-gray-800 mb-2">
                  商品情報
                </h2>
                <div className="flex flex-col space-y-2">
                  <div className="flex items-center space-x-4">
                    <p className="w-24 text-gray-600 font-medium">カテゴリー</p>
                    {itemCategories.length > 0 ? (
                      <ul className="flex flex-wrap gap-2">
                        {itemCategories.map((category, index) => (
                          <li
                            key={`${category}-${index}`}
                            className="px-3 py-1 bg-gray-200 text-gray-700 text-sm rounded-full"
                          >
                            {category}
                          </li>
                        ))}
                      </ul>
                    ) : (
                      <p className="text-gray-500">
                        カテゴリーは登録されていません。
                      </p>
                    )}
                  </div>
                </div>
              </div>
            </div>

            {/* 状態 */}
            <div className={`${styles.item_detail_condition} mt-4`}>
              <div className="flex items-center space-x-4">
                <p className="w-24 text-gray-600 font-medium">商品の状態</p>
                <p className="text-gray-700 font-semibold">
                  {item.condition ?? "未登録"}
                </p>
              </div>
            </div>

            {/* コメント履歴 */}
            <div
              className={`${styles.item_detail_comment_history} mt-10 border-t border-gray-200 pt-6`}
            >
              <div
                className={`${styles.comment_count_flex} flex justify-between items-center mb-4`}
              >
                <h2 className="text-xl font-bold text-gray-800">コメント</h2>
                <span className={styles.comments_count}>
                  ({comments.length})
                </span>
              </div>

              {comments.length > 0 ? (
                <div className="max-h-80 overflow-y-auto pr-2 pt-2 space-y-4">
                  {comments.map((comment) => (
                    <div
                      key={comment.id}
                      className={`${styles.comment} border-b border-gray-100 pb-3`}
                    >
                      <div
                        className={`${styles.comment_name_image} flex items-center space-x-3`}
                      >
                        <img
                          src={getImageUrl(
                            comment.user.user_image,
                            IMAGE_TYPE.USER,
                          )}
                          alt="プロフィール画像"
                          className={`${styles.user_image_css} w-10 h-10 rounded-full object-cover`}
                          onError={(e) => onImageError(e, comment.user.name)}
                        />
                        <p
                          className={`${styles.comment_name} font-semibold text-gray-800`}
                        >
                          {comment.user.name}
                        </p>
                      </div>
                      <p
                        className={`${styles["comment-text"]} ml-10 mt-1 text-gray-700 whitespace-pre-wrap`}
                      >
                        {comment.comment}
                      </p>
                      <small className="text-xs ml-10 text-gray-500 block mt-1">
                        投稿日時:{" "}
                        {new Date(comment.created_at).toLocaleString()}
                      </small>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="mt-4 ml-5 text-gray-500 text-sm">
                  まだコメントはありません。
                </p>
              )}
            </div>

            {/* コメント投稿フォーム */}
            <div className={`${styles.item_detail_comment_form} mt-10`}>
              <h2 className="text-xl font-bold text-gray-800 mb-4">
                商品へのコメント
              </h2>

              {commentErrors.length > 0 && (
                <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-3 mb-4 rounded">
                  <ul>
                    {commentErrors.map((err, index) => (
                      <li key={`${err}-${index}`} className="text-sm">
                        {err}
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {isAuthenticated ? (
                <form
                  onSubmit={(e: FormEvent) => {
                    e.preventDefault();
                    void submitComment();
                  }}
                  className="space-y-3"
                >
                  <textarea
                    value={newComment}
                    onChange={(e) => setNewComment(e.target.value)}
                    rows={5}
                    placeholder="コメントを入力してください"
                    className="w-full p-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-red-500 resize-none text-gray-700"
                    disabled={isSubmittingComment || totalLoading}
                  />
                  <button
                    type="submit"
                    className="w-full py-3 bg-red-600 text-white font-bold rounded-lg hover:bg-red-700 transition duration-200 disabled:bg-red-300"
                    disabled={
                      isSubmittingComment ||
                      totalLoading ||
                      newComment.trim() === ""
                    }
                  >
                    {isSubmittingComment ? "投稿中..." : "コメントを送信する"}
                  </button>
                </form>
              ) : (
                <div className="text-center p-4 border border-dashed rounded-lg">
                  <button
                    type="button"
                    onClick={() => router.push("/login")}
                    className="text-red-600 font-semibold cursor-pointer hover:underline"
                  >
                    ログインしてコメントする
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
